using System;using System.IO;using System.Diagnostics;using System.Windows.Forms;
class WindowReviewParent {
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();var parent=new Form{StartPosition=FormStartPosition.Manual,Left=380,Top=220,Width=1700,Height=1000,ShowInTaskbar=false};var handle=parent.Handle;var context=new ApplicationContext();Process child=null;DateTime start=DateTime.UtcNow;var timer=new Timer{Interval=200};timer.Tick+=(s,e)=>{if(child==null){child=Process.Start(new ProcessStartInfo(args[0],"-parentHWND "+handle.ToInt64()+" -popupwindow -screen-fullscreen 0 -screen-width 1280 -screen-height 720 -scratch-window-review -logFile \""+args[1]+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Environment.CurrentDirectory});}if(child.HasExited){Environment.ExitCode=child.ExitCode;timer.Stop();parent.Dispose();context.ExitThread();}else if((DateTime.UtcNow-start).TotalSeconds>60){child.Kill();Environment.ExitCode=4;timer.Stop();parent.Dispose();context.ExitThread();}};timer.Start();Application.Run(context);}
}
